(function(){'use strict';
var DATA={"label": "Feature Selection Engine - Signature build-tool concept", "rows": [["scikit-learn", "86"], ["  scikit-learn ", "79"], ["PyTorch", "51"], ["TensorFlow", "41"], ["  TensorFlow ", "84"], ["XGBoost", "63"], ["k-means clustering", "64"], ["  k-means clustering ", "96"], ["", ""], ["scikit-learn", "42"]]};

var seen={},kept=[],droppedEmpty=0,droppedDup=0;
